"use client";

import { useEffect, useMemo, useState } from "react";
import { Activity, Archive, ArrowDown, ArrowLeft, ArrowUp, BookOpen, Check, ChevronRight, CircleUserRound, Compass, Eye, FilePlus2, FileText, HeartPulse, Images, ListPlus, Map, MapPin, MessageCircle, Pin, Plus, RefreshCw, Save, Search, Trash2, X } from "lucide-react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import PhotoUploader from "@/components/control/photo-uploader";
import MessagesEditor from "@/components/control/messages-editor";

type Module = "notes" | "now" | "places" | "photos" | "messages" | "browser" | "human" | "update" | "activity" | "trash";
type BlockType = "paragraph" | "heading1" | "heading2" | "bullet" | "quote";
type Block = { id: string; type: BlockType; text: string };
type Link = { label: string; url: string };
type Note = { id?: string; title: string; slug: string; excerpt: string; bodyMarkdown: string; publicationState: "draft" | "published"; pinned: boolean; folderSlug: string | null; tags: string[]; sourcePublishedAt: string | null; publishedAt: string | null; editorialNotice: string; externalLinks: Link[]; updatedAt?: string };
type BookOption = { id: string; slug: string; title: string; authors: string[]; cover: string };
type VisitOption = { id: string; placeId: string; label: string; publicBlurb: string; whereStayed: string; favoriteThings: string[]; foodDrink: string[] };
type ControlData = { admin: { displayName: string; email: string }; notes: Note[]; folders: Array<{ id: string; slug: string; label: string }>; currentState: any; bookOptions: BookOption[]; bookIntakes: any[]; softwareUpdate: any; trash: any[]; activity: any[]; human: any[]; humanRelationshipOptions: any[]; browser: any[]; messages: any[]; photos: any[]; photoVisitOptions: VisitOption[] };

const blankNote = (): Note => ({ title: "", slug: "", excerpt: "", bodyMarkdown: "", publicationState: "draft", pinned: false, folderSlug: "ideas", tags: [], sourcePublishedAt: null, publishedAt: null, editorialNotice: "", externalLinks: [] });

export default function ControlCenter() {
  const [data, setData] = useState<ControlData | null>(null);
  const [module, setModule] = useState<Module>("notes");
  const [selectedNote, setSelectedNote] = useState<Note | null>(null);
  const [mobileDetail, setMobileDetail] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [toast, setToast] = useState("");

  async function load() {
    setLoading(true); setError("");
    const response = await fetch("/api/control/content", { cache: "no-store" });
    if (response.status === 401) { window.location.href = "/control/login"; return; }
    const value = await response.json();
    if (!response.ok) setError(value.error || "Control Center could not load.");
    else { setData(value); setSelectedNote((current) => current ? value.notes.find((note: Note) => note.id === current.id) || current : value.notes[0] || null); }
    setLoading(false);
  }
  useEffect(() => { load(); }, []);
  function notify(message: string) { setToast(message); window.setTimeout(() => setToast(""), 2600); }

  if (loading && !data) return <main className="control-loading"><RefreshCw/><strong>Opening Control Center…</strong></main>;
  if (error && !data) return <main className="control-loading"><strong>Something interrupted the signal.</strong><p>{error}</p><button onClick={load}>Try again</button></main>;
  if (!data) return null;

  return <main className="control-center">
    <header className="control-topbar"><div className="control-brand"><span>S</span><div><strong>Control Center</strong><small>Synergetic Human</small></div></div><div className="control-user"><span><strong>{data.admin.displayName}</strong><small>Administrator</small></span><CircleUserRound/><form action="/control/logout" method="post"><button>Sign out</button></form></div></header>
    <aside className="control-nav">
      <div><span>EDIT</span><NavButton id="notes" label="Notes" icon={<FileText/>} active={module === "notes"} onClick={() => { setModule("notes"); setMobileDetail(false); }}/><NavButton id="now" label="NOW" icon={<MapPin/>} active={module === "now"} onClick={() => { setModule("now"); setMobileDetail(true); }}/><NavButton id="places" label="Places" icon={<Map/>} active={module === "places"} onClick={() => { setModule("places"); setMobileDetail(true); }}/><NavButton id="photos" label="Photos" icon={<Images/>} active={module === "photos"} onClick={() => { setModule("photos"); setMobileDetail(true); }}/><NavButton id="messages" label="Messages" icon={<MessageCircle/>} active={module === "messages"} onClick={() => { setModule("messages"); setMobileDetail(true); }}/><NavButton id="browser" label="Browser" icon={<Compass/>} active={module === "browser"} onClick={() => { setModule("browser"); setMobileDetail(true); }}/><NavButton id="human" label="Human" icon={<HeartPulse/>} active={module === "human"} onClick={() => { setModule("human"); setMobileDetail(true); }}/><NavButton id="update" label="Software Update" icon={<RefreshCw/>} active={module === "update"} onClick={() => { setModule("update"); setMobileDetail(true); }}/><NavButton id="activity" label="Activity" icon={<Activity/>} active={module === "activity"} onClick={() => { setModule("activity"); setMobileDetail(true); }}/><NavButton id="trash" label="Trash" icon={<Trash2/>} active={module === "trash"} onClick={() => { setModule("trash"); setMobileDetail(true); }}/></div>
      <footer><a href="/" target="_blank">Open public OS <Eye/></a><small>Changes appear on staging after save.</small></footer>
    </aside>
    <section className={`control-workspace ${mobileDetail ? "shows-detail" : "shows-index"}`}>
      {module === "notes" && <NotesModule data={data} selected={selectedNote} setSelected={(note) => { setSelectedNote(note); setMobileDetail(true); }} onBack={() => setMobileDetail(false)} reload={load} notify={notify}/>}
      {module === "now" && <NowEditor state={data.currentState} books={data.bookOptions} onBack={() => { setMobileDetail(false); setModule("notes"); }} reload={load} notify={notify}/>}
      {module === "places" && <PlacesEditor visits={data.photoVisitOptions || []} onBack={() => { setMobileDetail(false); setModule("notes"); }} reload={load} notify={notify}/>}
      {module === "photos" && <PhotosEditor items={data.photos || []} visits={data.photoVisitOptions || []} onBack={() => { setMobileDetail(false); setModule("notes"); }} reload={load} notify={notify}/>}
      {module === "messages" && <MessagesEditor items={data.messages || []} onBack={() => { setMobileDetail(false); setModule("notes"); }} reload={load} notify={notify}/>}
      {module === "browser" && <BrowserEditor items={data.browser} entityOptions={data.humanRelationshipOptions} humanOptions={data.human} onBack={() => { setMobileDetail(false); setModule("notes"); }} reload={load} notify={notify}/>}
      {module === "human" && <HumanEditor items={data.human.filter((item:any)=>item.section!=="frontiers")} relationshipOptions={data.humanRelationshipOptions} onBack={() => { setMobileDetail(false); setModule("notes"); }} reload={load} notify={notify}/>}
      {module === "update" && <SoftwareEditor update={data.softwareUpdate} onBack={() => { setMobileDetail(false); setModule("notes"); }} reload={load} notify={notify}/>} 
      {module === "activity" && <ActivityEditor items={data.activity} onBack={() => { setMobileDetail(false); setModule("notes"); }} reload={load} notify={notify}/>}
      {module === "trash" && <TrashEditor items={data.trash} onBack={() => { setMobileDetail(false); setModule("notes"); }} reload={load} notify={notify}/>} 
    </section>
    {toast && <div className="control-toast"><Check/>{toast}</div>}
  </main>;
}

function NavButton({ label, icon, active, onClick }: { id: string; label: string; icon: React.ReactNode; active: boolean; onClick: () => void }) { return <button className={active ? "is-active" : ""} onClick={onClick}>{icon}<strong>{label}</strong><ChevronRight/></button>; }

function NotesModule({ data, selected, setSelected, onBack, reload, notify }: { data: ControlData; selected: Note | null; setSelected: (note: Note) => void; onBack: () => void; reload: () => Promise<void>; notify: (value: string) => void }) {
  const [query, setQuery] = useState("");
  const filtered = data.notes.filter((note) => `${note.title} ${note.tags.join(" ")}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="control-notes">
    <section className="control-note-index"><div className="mobile-section-head"><strong>Notes</strong></div><div className="control-section-title"><div><h1>Notes</h1><p>{data.notes.length} living documents</p></div><button onClick={() => setSelected(blankNote())}><FilePlus2/> New</button></div><label className="control-search">⌕<input placeholder="Search notes" value={query} onChange={(event) => setQuery(event.target.value)}/></label><div className="control-note-list">{filtered.map((note) => <button key={note.id} className={selected?.id === note.id ? "is-selected" : ""} onClick={() => setSelected(note)}><span><strong>{note.title || "Untitled"}</strong>{note.pinned && <Pin/>}</span><small>{note.publicationState === "published" ? "Published" : "Draft"} · {note.folderSlug || "No folder"}</small><p>{note.excerpt || "No summary yet."}</p><ChevronRight/></button>)}</div></section>
    <NoteEditor key={selected?.id || "new"} note={selected || blankNote()} folders={data.folders} onBack={onBack} reload={reload} notify={notify}/>
  </div>;
}

function NoteEditor({ note: initial, folders, onBack, reload, notify }: { note: Note; folders: ControlData["folders"]; onBack: () => void; reload: () => Promise<void>; notify: (value: string) => void }) {
  const [note, setNote] = useState<Note>({ ...initial, externalLinks: initial.externalLinks || [], tags: initial.tags || [] });
  const [blocks, setBlocks] = useState<Block[]>(parseMarkdown(initial.bodyMarkdown));
  const [preview, setPreview] = useState(false);
  const [saving, setSaving] = useState(false);
  const markdown = useMemo(() => serializeBlocks(blocks), [blocks]);
  const update = (changes: Partial<Note>) => setNote((current) => ({ ...current, ...changes }));
  const changeTitle = (title: string) => update({ title, ...(!note.id || !note.slug ? { slug: slugify(title) } : {}) });

  async function save(publicationState: "draft" | "published") {
    if (publicationState === "published" && !window.confirm("Publish this note to the public OS now?")) return;
    if (publicationState === "draft" && note.publicationState === "published" && !window.confirm("Unpublish this note and return it to Drafts?")) return;
    setSaving(true);
    const response = await action({ action: "save-note", note: { ...note, bodyMarkdown: markdown, publicationState }, confirmPublish: publicationState === "published" });
    setSaving(false);
    if (!response.ok) return window.alert(response.error);
    notify(publicationState === "published" ? "Note published" : "Draft saved"); await reload();
  }
  async function archive() {
    if (!note.id || !window.confirm("Archive this note? It will disappear publicly but can be recovered from the database.")) return;
    const response = await action({ action: "archive-note", id: note.id, confirm: true });
    if (!response.ok) return window.alert(response.error); notify("Note archived"); await reload(); onBack();
  }
  return <section className="control-note-editor">
    <header className="editor-header"><button className="mobile-back" onClick={onBack}><ArrowLeft/> Notes</button><Status state={note.publicationState}/><div><button onClick={() => setPreview(true)}><Eye/> Preview</button><button className="primary" disabled={saving} onClick={() => save(note.publicationState)}><Save/>{saving ? "Saving…" : note.publicationState === "published" ? "Update" : "Save draft"}</button></div></header>
    <div className="editor-scroll"><label className="title-input"><span>Title</span><input value={note.title} onChange={(event) => changeTitle(event.target.value)} placeholder="A note worth keeping"/></label><div className="editor-two"><Field label="Slug"><input value={note.slug} onChange={(event) => update({ slug: slugify(event.target.value) })} placeholder="a-note-worth-keeping"/></Field><Field label="Folder"><select value={note.folderSlug || ""} onChange={(event) => update({ folderSlug: event.target.value || null })}><option value="">No folder</option>{folders.map((folder) => <option key={folder.id} value={folder.slug}>{folder.label}</option>)}</select></Field></div><Field label="Short description"><textarea rows={2} value={note.excerpt} onChange={(event) => update({ excerpt: event.target.value })} placeholder="What is this note about?"/></Field>
      <div className="editor-writing-head"><div><strong>Writing</strong><small>Build the note in simple blocks. No Markdown required.</small></div><button onClick={() => setBlocks((current) => [...current, newBlock("paragraph")])}><Plus/> Add block</button></div><div className="block-editor">{blocks.map((block, index) => <BlockRow key={block.id} block={block} index={index} total={blocks.length} update={(value) => setBlocks((current) => current.map((item) => item.id === block.id ? { ...item, ...value } : item))} move={(direction) => setBlocks((current) => moveItem(current, index, index + direction))} remove={() => setBlocks((current) => current.filter((item) => item.id !== block.id))}/>)}</div>
      <div className="editor-two"><Field label="Tags"><input value={note.tags.join(", ")} onChange={(event) => update({ tags: event.target.value.split(",").map((tag) => tag.trim()).filter(Boolean) })} placeholder="travel, ideas"/></Field><Field label="Original/source date"><input type="date" value={note.sourcePublishedAt || ""} onChange={(event) => update({ sourcePublishedAt: event.target.value || null })}/></Field></div><Field label="Editorial context (optional)"><textarea rows={2} value={note.editorialNotice} onChange={(event) => update({ editorialNotice: event.target.value })} placeholder="A subtle public note about context or uncertainty"/></Field>
      <LinkEditor links={note.externalLinks} setLinks={(externalLinks) => update({ externalLinks })}/>
      <div className="publish-panel"><label><input type="checkbox" checked={note.pinned} onChange={(event) => update({ pinned: event.target.checked })}/><span><strong>Pin this note</strong><small>Keep it easy to find in public Notes.</small></span></label><div><button onClick={() => save("draft")}>{note.publicationState === "published" ? "Unpublish" : "Save draft"}</button><button className="publish" onClick={() => save("published")}>{note.publicationState === "published" ? "Update published note" : "Review & publish"}</button></div></div>{note.id && <button className="danger-link" onClick={archive}><Archive/> Archive note</button>}
    </div>
    {preview && <Preview note={{ ...note, bodyMarkdown: markdown }} close={() => setPreview(false)}/>} 
  </section>;
}

function BlockRow({ block, index, total, update, move, remove }: { block: Block; index: number; total: number; update: (value: Partial<Block>) => void; move: (direction: number) => void; remove: () => void }) { return <div className={`writing-block is-${block.type}`}><div className="block-controls"><select value={block.type} onChange={(event) => update({ type: event.target.value as BlockType })}><option value="paragraph">Text</option><option value="heading1">Title</option><option value="heading2">Heading</option><option value="bullet">Bullet</option><option value="quote">Quote</option></select><button disabled={index === 0} onClick={() => move(-1)} aria-label="Move up"><ArrowUp/></button><button disabled={index === total - 1} onClick={() => move(1)} aria-label="Move down"><ArrowDown/></button><button onClick={remove} aria-label="Remove block"><X/></button></div><textarea rows={block.type === "paragraph" || block.type === "quote" ? 3 : 1} value={block.text} onChange={(event) => update({ text: event.target.value })} placeholder={block.type === "heading2" ? "Section heading" : block.type === "bullet" ? "List item" : "Write something…"}/></div>; }

function LinkEditor({ links, setLinks }: { links: Link[]; setLinks: (links: Link[]) => void }) { return <div className="link-editor"><div><strong>Links</strong><button onClick={() => setLinks([...links, { label: "", url: "" }])}><Plus/> Add link</button></div>{links.map((link, index) => <div key={index}><input value={link.label} onChange={(event) => setLinks(links.map((item, i) => i === index ? { ...item, label: event.target.value } : item))} placeholder="Label"/><input value={link.url} onChange={(event) => setLinks(links.map((item, i) => i === index ? { ...item, url: event.target.value } : item))} placeholder="https://…" inputMode="url"/><button onClick={() => setLinks(links.filter((_, i) => i !== index))}><X/></button></div>)}</div>; }

function Preview({ note, close }: { note: Note; close: () => void }) { return <div className="control-preview"><header><div><Status state={note.publicationState}/><span>Private preview</span></div><button onClick={close}><X/> Close</button></header><article>{note.editorialNotice && <aside>{note.editorialNotice}</aside>}<ReactMarkdown remarkPlugins={[remarkGfm]}>{note.bodyMarkdown}</ReactMarkdown></article></div>; }

function NowEditor({ state: initial, books, onBack, reload, notify }: { state: any; books: BookOption[]; onBack: () => void; reload: () => Promise<void>; notify: (value: string) => void }) {
  const [state, setState] = useState(initial || {}); const [saving, setSaving] = useState(false);
  const set = (key: string, value: any) => setState((current: any) => ({ ...current, [key]: value }));
  async function save() { setSaving(true); const response = await action({ action: "save-current-state", state }); setSaving(false); if (!response.ok) return window.alert(response.error); notify("NOW updated everywhere"); await reload(); }
  return <EditorPage title="NOW" subtitle="The living state of the system. Blank is completely fine." onBack={onBack} action={<button className="primary" onClick={save} disabled={saving}><Save/>{saving ? "Saving…" : "Update NOW"}</button>}><div className="now-grid"><Field label="City"><input value={state.where?.city || ""} onChange={(event) => set("where", { ...state.where, city: event.target.value })}/></Field><Field label="Country"><input value={state.where?.country || ""} onChange={(event) => set("where", { ...state.where, country: event.target.value })}/></Field><Field label="Coordinates (optional)"><input value={state.where?.coordinates || ""} onChange={(event) => set("where", { ...state.where, coordinates: event.target.value })}/></Field><div className="reading-pickers"><ReadingBookPicker label="Reading now" idKey="readingBookId" textKey="reading" state={state} books={books} set={set}/><ReadingBookPicker label="Also reading · optional" idKey="readingBookIdSecondary" textKey="readingSecondary" state={state} books={books} set={set}/></div><div className="reading-pickers reading-pickers--recent"><ReadingBookPicker label="Recently read · first" idKey="recentlyReadBookId" textKey="recentlyRead" state={state} books={books} set={set} allowManual={false}/><ReadingBookPicker label="Recently read · second" idKey="recentlyReadBookIdSecondary" textKey="recentlyReadSecondary" state={state} books={books} set={set} allowManual={false}/></div><Field label="Thinking"><input value={state.thinking || ""} onChange={(event) => set("thinking", event.target.value)}/></Field><Field label="Making"><input value={state.making || ""} onChange={(event) => set("making", event.target.value)}/></Field><Field label="Training"><input value={state.training || ""} onChange={(event) => set("training", event.target.value)}/></Field><Field label="Eating lately"><input value={state.eatingLately || ""} onChange={(event) => set("eatingLately", event.target.value)}/></Field><Field label="Listening to"><input value={state.listening || ""} onChange={(event) => set("listening", event.target.value)}/></Field></div><p className="editorial-hint">Older Current Thought, Current Question, Trying to Understand, Rabbit Holes, and Experiments values remain preserved in earlier snapshots; NOW uses one public Thinking field.</p><section className="battery-editor"><div><strong>Human Battery</strong><small>Manual check-in only. Clear it whenever it stops feeling current.</small></div><label><input type="checkbox" checked={typeof state.humanBattery?.level === "number"} onChange={(event) => set("humanBattery", event.target.checked ? { level: 50, label: "Half charged", note: "" } : { level: null, label: "Unreported", note: null })}/> Report a battery level</label>{typeof state.humanBattery?.level === "number" && <><input type="range" min="0" max="100" value={state.humanBattery.level} onChange={(event) => set("humanBattery", { ...state.humanBattery, level: Number(event.target.value) })}/><strong>{state.humanBattery.level}%</strong><input value={state.humanBattery.label || ""} onChange={(event) => set("humanBattery", { ...state.humanBattery, label: event.target.value })} placeholder="Running beautifully weird"/><input value={state.humanBattery.note || ""} onChange={(event) => set("humanBattery", { ...state.humanBattery, note: event.target.value })} placeholder="Optional note"/></>}</section></EditorPage>;
}

function ReadingBookPicker({ label, idKey, textKey, state, books, set, allowManual = true }: { label: string; idKey: string; textKey: string; state: any; books: BookOption[]; set: (key: string, value: any) => void; allowManual?: boolean }) {
  const [created, setCreated] = useState<BookOption | null>(null);
  const linked = books.find((book) => book.id === state[idKey]) || (created?.id === state[idKey] ? created : null);
  const [query, setQuery] = useState(linked?.title || "");
  const [open, setOpen] = useState(false);
  const authorKey = `${textKey}Author`;
  const initialParts = !state[idKey] && !state[authorKey] ? String(state[textKey] || "").match(/^(.+?)\s+by\s+([^,]+)$/i) : null;
  const [newTitle, setNewTitle] = useState(initialParts?.[1]?.trim() || state[textKey] || "");
  const [newAuthor, setNewAuthor] = useState(initialParts?.[2]?.trim() || state[authorKey] || "");
  const [highlightsReference, setHighlightsReference] = useState("");
  const [adding, setAdding] = useState(false);
  const matches = useMemo(() => {
    const needle = query.trim().toLowerCase();
    if (!needle) return books.slice(0, 8);
    return books.filter((book) => `${book.title} ${book.authors.join(" ")}`.toLowerCase().includes(needle)).slice(0, 8);
  }, [books, query]);
  const choose = (book: BookOption) => { set(idKey, book.id); set(textKey, book.title); setQuery(book.title); setOpen(false); };
  const change = () => { set(idKey, null); set(textKey, ""); setQuery(""); setOpen(true); setNewTitle(linked?.title || ""); setNewAuthor(linked?.authors.join(", ") || ""); };
  const remove = () => { set(idKey, null); set(textKey, ""); set(authorKey, null); setQuery(""); setOpen(false); setNewTitle(""); setNewAuthor(""); };
  async function addBook() {
    setAdding(true);
    const response = await fetch("/api/control/book-intake", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ title: newTitle, author: newAuthor, highlightsReference }) });
    const result = await response.json(); setAdding(false);
    if (!response.ok) return window.alert(result.error || "The book could not be added.");
    setCreated(result.book); set(idKey, result.book.id); set(textKey, result.book.title); set(authorKey, result.book.authors[0] || newAuthor); setQuery(result.book.title); setOpen(false);
  }
  return <section className="reading-book-picker"><span>{label}</span>{linked ? <div className="linked-book-card"><img src={linked.cover} alt=""/><div><small>LINKED TO BOOKS</small><strong>{linked.title}</strong><span>{linked.authors.join(", ") || "Author not recorded"}</span></div><div className="linked-book-actions"><button type="button" onClick={change}>Change</button><button type="button" onClick={remove}>Remove</button></div></div> : <><label><Search/><input value={query} onFocus={() => setOpen(true)} onChange={(event) => { setQuery(event.target.value); setOpen(true); }} placeholder="Search your Library…"/></label>{open && <div className="book-picker-results">{matches.map((book) => <button type="button" key={book.id} onClick={() => choose(book)}><img src={book.cover} alt=""/><span><strong>{book.title}</strong><small>{book.authors.join(", ") || "Author not recorded"}</small></span><BookOpen/></button>)}{!matches.length && <p>Not in your Library yet. Add it below.</p>}</div>}{allowManual && <div className="new-book-intake"><div className="new-book-intake-head"><strong>Add a new book</strong><small>This creates a real Library entry and looks for a lawful cover.</small></div><Field label="Title"><input value={newTitle} onChange={(event) => { setNewTitle(event.target.value); set(textKey, event.target.value); }} placeholder="Book title"/></Field><Field label="Author"><input value={newAuthor} onChange={(event) => { setNewAuthor(event.target.value); set(authorKey, event.target.value); }} placeholder="Author name"/></Field><Field label="Where should I find the highlights? · private"><textarea rows={2} value={highlightsReference} onChange={(event) => setHighlightsReference(event.target.value)} placeholder="Paste a Google Doc link, local folder/path, or a short instruction for later import."/></Field><button type="button" className="add-library-book" disabled={adding || !newTitle.trim() || !newAuthor.trim()} onClick={addBook}><BookOpen/>{adding ? "Finding the book…" : "Add to Library"}</button><small className="intake-privacy">Highlights are queued for later import and are never published from this field.</small></div>}</>}</section>;
}

function PlacesEditor({ visits, onBack, reload, notify }: { visits: VisitOption[]; onBack: () => void; reload: () => Promise<void>; notify: (value: string) => void }) {
  const [query, setQuery] = useState("");
  const [editing, setEditing] = useState<VisitOption | null>(null);
  const [saving, setSaving] = useState(false);
  const filtered = visits.filter((visit) => visit.label.toLowerCase().includes(query.toLowerCase())).slice().reverse();
  async function save() {
    if (!editing) return;
    setSaving(true);
    const response = await action({ action: "save-visit-reflection", visit: editing });
    setSaving(false);
    if (!response.ok) return window.alert(response.error);
    notify(editing.publicBlurb.trim() ? "Place reflection published" : "Place reflection cleared");
    setEditing(null); await reload();
  }
  return <EditorPage title="Places" subtitle="Small memories from the route—not destination guides." onBack={onBack} action={<span/>}><p className="editorial-hint">Add a quick public reflection when you have something worth saying. Blank visits stay quiet. The original route and dates are never changed here.</p><label className="control-photo-search"><Search/><input value={query} onChange={(event)=>setQuery(event.target.value)} placeholder="Find a place or date"/></label><div className="place-reflection-list">{filtered.map((visit)=><button key={visit.id} onClick={()=>setEditing({...visit})}><span><strong>{visit.label}</strong><small>{visit.publicBlurb || "No reflection yet"}</small></span><ChevronRight/></button>)}</div>{editing&&<div className="inline-sheet place-reflection-sheet"><header><div><strong>{editing.label}</strong><small>Shown publicly only when text exists.</small></div><button onClick={()=>setEditing(null)}><X/></button></header><Field label="A quick reflection"><textarea autoFocus rows={7} maxLength={2000} value={editing.publicBlurb} onChange={(event)=>setEditing({...editing,publicBlurb:event.target.value})} placeholder="What do you remember about being here?"/></Field><div className="place-reflection-actions"><small>{editing.publicBlurb.length}/2000</small><button className="primary" disabled={saving} onClick={save}><Save/>{saving?"Saving…":"Save reflection"}</button></div><p className="editorial-hint">Where you stayed, favorite things, and food can become optional fields later. This pass keeps writing deliberately simple.</p></div>}</EditorPage>;
}

function PhotosEditor({ items, visits, onBack, reload, notify }: { items: any[]; visits: ControlData["photoVisitOptions"]; onBack: () => void; reload: () => Promise<void>; notify: (value: string) => void }) {
  const [query, setQuery] = useState(""); const [saving, setSaving] = useState<string | null>(null);
  const [drafts, setDrafts] = useState<Record<string, any>>({});
  const filtered = items.filter((item) => `${item.displayPlace || ""} ${item.country || ""} ${item.capturedOn || ""}`.toLowerCase().includes(query.toLowerCase()));
  const valueFor = (item: any) => drafts[item.id] || item;
  const change = (item: any, values: any) => setDrafts((current) => ({ ...current, [item.id]: { ...valueFor(item), ...values } }));
  async function save(item: any) { const value = valueFor(item); setSaving(item.id); const response = await action({ action: "save-photo-editorial", photo: value }); setSaving(null); if (!response.ok) return window.alert(response.error); notify("Photo updated"); setDrafts((current) => { const next = { ...current }; delete next[item.id]; return next; }); await reload(); }
  return <EditorPage title="Photos" subtitle="Add new memories, then make small public corrections." onBack={onBack} action={<span/>}><PhotoUploader visits={visits} reload={reload} notify={notify}/><p className="editorial-hint">Existing photos: manage public visibility, Wallpaper status, and the reviewable Journey visit. Capture metadata and private originals stay protected.</p><label className="control-photo-search"><Search/><input value={query} onChange={(event)=>setQuery(event.target.value)} placeholder="Find by place or date"/></label>{!items.length ? <div className="control-photo-empty">No photos yet.</div> : <div className="control-photo-grid">{filtered.map((item) => { const value = valueFor(item); const dirty = Boolean(drafts[item.id]); return <article key={item.id}><img src={item.thumbnail} alt=""/><div className="control-photo-meta"><strong>{item.displayPlace || "Unplaced"}</strong><span>{item.country || ""} · {item.capturedOn || "Date unavailable"}</span><label>Journey visit<select value={value.visitId || ""} onChange={(event)=>change(item,{visitId:event.target.value||null})}><option value="">Unassigned</option>{visits.map((visit)=><option value={visit.id} key={visit.id}>{visit.label}</option>)}</select></label><div><label><input type="checkbox" checked={Boolean(value.visible)} onChange={(event)=>change(item,{visible:event.target.checked})}/> Public</label><label><input type="checkbox" checked={Boolean(value.wallpaper)} onChange={(event)=>change(item,{wallpaper:event.target.checked})}/> Wallpaper</label></div></div><button disabled={!dirty || saving===item.id} onClick={()=>save(item)}>{saving===item.id?"Saving…":"Save"}</button></article>; })}</div>}</EditorPage>;
}

function SoftwareEditor({ update: initial, onBack, reload, notify }: { update: any; onBack: () => void; reload: () => Promise<void>; notify: (value: string) => void }) { const [update, setUpdate] = useState(initial || { versionLabel: "Current", new: [], currentlyExploring: [], performance: [], knownIssues: [] }); const [saving, setSaving] = useState(false); async function save(){setSaving(true);const response=await action({action:"save-software-update",update});setSaving(false);if(!response.ok)return window.alert(response.error);notify("Software Update published");await reload();} return <EditorPage title="Software Update" subtitle="Release notes for a human in motion." onBack={onBack} action={<button className="primary" onClick={save} disabled={saving}><Save/>{saving?"Saving…":"Publish update"}</button>}><Field label="Version label"><input value={update.versionLabel} onChange={(event)=>setUpdate({...update,versionLabel:event.target.value})}/></Field><ItemList title="New" items={update.new||[]} setItems={(items)=>setUpdate({...update,new:items})}/><ItemList title="Currently Exploring" items={update.currentlyExploring||[]} setItems={(items)=>setUpdate({...update,currentlyExploring:items})}/><ItemList title="Performance" items={update.performance||[]} setItems={(items)=>setUpdate({...update,performance:items})}/><ItemList title="Known Issues" items={update.knownIssues||[]} setItems={(items)=>setUpdate({...update,knownIssues:items})}/></EditorPage>; }

function TrashEditor({ items, onBack, reload, notify }: { items: any[]; onBack: () => void; reload: () => Promise<void>; notify: (value: string) => void }) { const [editing, setEditing] = useState<any>(null); async function save(item:any){const response=await action({action:"save-trash",item});if(!response.ok)return window.alert(response.error);notify("Trash updated");setEditing(null);await reload();} async function archive(id:string){if(!window.confirm("Archive this Trash record?"))return;const response=await action({action:"archive-trash",id,confirm:true});if(!response.ok)return window.alert(response.error);notify("Trash record archived");await reload();} return <EditorPage title="Trash" subtitle="Things worth releasing, or at least laughing about later." onBack={onBack} action={<button className="primary" onClick={()=>setEditing({title:"",description:"",category:"belief",trashedAt:"",state:"trashed",visibility:"public",sortOrder:(items.length+1)*10})}><Plus/> Add record</button>}><div className="trash-control-list">{items.map((item)=><article key={item.id}><div><strong>{item.title}</strong><span>{item.category} · {item.state}</span><p>{item.description}</p></div><button onClick={()=>setEditing({...item,trashedAt:item.trashed_at,sortOrder:item.sort_order})}>Edit</button><button className="icon-danger" onClick={()=>archive(item.id)}><Archive/></button></article>)}</div>{editing&&<div className="inline-sheet"><header><strong>{editing.id?"Edit record":"New Trash record"}</strong><button onClick={()=>setEditing(null)}><X/></button></header><Field label="Title"><input value={editing.title} onChange={(event)=>setEditing({...editing,title:event.target.value})}/></Field><Field label="Short description"><textarea rows={2} value={editing.description} onChange={(event)=>setEditing({...editing,description:event.target.value})}/></Field><div className="editor-two"><Field label="Category"><input value={editing.category} onChange={(event)=>setEditing({...editing,category:event.target.value})}/></Field><Field label="Trashed date"><input type="date" value={editing.trashedAt||""} onChange={(event)=>setEditing({...editing,trashedAt:event.target.value})}/></Field><Field label="State"><select value={editing.state} onChange={(event)=>setEditing({...editing,state:event.target.value})}><option value="trashed">Trashed</option><option value="restored">Put Back</option><option value="active">Active</option></select></Field><Field label="Visibility"><select value={editing.visibility} onChange={(event)=>setEditing({...editing,visibility:event.target.value})}><option value="public">Public</option><option value="private">Private</option></select></Field></div><button className="primary full" onClick={()=>save(editing)}><Save/> Save record</button></div>}</EditorPage>; }

function ActivityEditor({ items, onBack, reload, notify }: { items: any[]; onBack: () => void; reload: () => Promise<void>; notify: (value: string) => void }) { const [editing,setEditing]=useState<any>(null); async function save(item:any){const response=await action({action:"save-activity",item});if(!response.ok)return window.alert(response.error);notify("Activity updated");setEditing(null);await reload();} async function archive(id:string){if(!window.confirm("Archive this process?"))return;const response=await action({action:"archive-activity",id,confirm:true});if(!response.ok)return window.alert(response.error);notify("Process archived");await reload();} return <EditorPage title="Activity Monitor" subtitle="A manual metaphor for what currently has your attention." onBack={onBack} action={<button className="primary" onClick={()=>setEditing({name:"",status:"background",detail:"",startedLabel:"",related:[],visibility:"public",editorialState:"approved",sortOrder:(items.length+1)*10})}><Plus/> Add process</button>}><p className="editorial-hint">Nothing here is tracked or inferred. These are short, manually authored process descriptions.</p><div className="trash-control-list">{items.map((item)=><article key={item.id}><div><strong>{item.name}</strong><span>{String(item.status).replace("_"," ")} · {item.visibility}</span><p>{item.detail}</p></div><button onClick={()=>setEditing({...item,startedLabel:item.started_label||"",related:item.related_items||[],editorialState:item.editorial_state,sortOrder:item.sort_order})}>Edit</button><button className="icon-danger" onClick={()=>archive(item.id)}><Archive/></button></article>)}</div>{editing&&<div className="inline-sheet"><header><strong>{editing.id?"Edit process":"New process"}</strong><button onClick={()=>setEditing(null)}><X/></button></header><Field label="Process name"><input value={editing.name} onChange={(event)=>setEditing({...editing,name:event.target.value})}/></Field><Field label="Small detail"><textarea rows={2} value={editing.detail} onChange={(event)=>setEditing({...editing,detail:event.target.value})}/></Field><div className="editor-two"><Field label="Status"><select value={editing.status} onChange={(event)=>setEditing({...editing,status:event.target.value})}><option value="running">Running</option><option value="background">Background</option><option value="sleeping">Sleeping</option><option value="not_responding">Not Responding</option></select></Field><Field label="Started label (optional)"><input value={editing.startedLabel||""} onChange={(event)=>setEditing({...editing,startedLabel:event.target.value})} placeholder="August 2026"/></Field><Field label="Related · comma separated"><input value={(editing.related||[]).join(", ")} onChange={(event)=>setEditing({...editing,related:event.target.value.split(",").map((value)=>value.trim()).filter(Boolean)})}/></Field><Field label="Visibility"><select value={editing.visibility} onChange={(event)=>setEditing({...editing,visibility:event.target.value})}><option value="public">Public</option><option value="private">Private</option></select></Field><Field label="Editorial state"><select value={editing.editorialState} onChange={(event)=>setEditing({...editing,editorialState:event.target.value})}><option value="approved">Approved</option><option value="needs_review">Needs review</option></select></Field></div><button className="primary full" onClick={()=>save(editing)}><Save/> Save process</button></div>}</EditorPage>; }

function BrowserEditor({ items, entityOptions, humanOptions, onBack, reload, notify }: { items:any[]; entityOptions:any[]; humanOptions:any[]; onBack:()=>void; reload:()=>Promise<void>; notify:(value:string)=>void }) {
  const blank={title:"",slug:"",centralQuestion:"",shortIntro:"",currentTake:"",status:"open",accent:"ember",publicationState:"draft",sortOrder:(items.length+1)*10,blocks:[],resources:[],entities:[],related:[],humanLinks:[]};
  const [editing,setEditing]=useState<any>(null);const [saving,setSaving]=useState(false);
  async function save(publicationState:"draft"|"published"){if(publicationState==="published"&&!window.confirm("Publish this rabbit hole to the public Browser now?"))return;if(publicationState==="draft"&&editing.publicationState==="published"&&!window.confirm("Unpublish this rabbit hole and return it to Draft?"))return;setSaving(true);const response=await action({action:"save-rabbit-hole",item:{...editing,publicationState},confirmPublish:publicationState==="published"});setSaving(false);if(!response.ok)return window.alert(response.error);notify(publicationState==="published"?"Rabbit hole published":"Rabbit hole draft saved");setEditing(null);await reload();}
  async function archive(id:string){if(!window.confirm("Archive this rabbit hole? It will disappear publicly but remain recoverable."))return;const response=await action({action:"archive-rabbit-hole",id,confirm:true});if(!response.ok)return window.alert(response.error);notify("Rabbit hole archived");setEditing(null);await reload();}
  const chosenEntities=new Set((editing?.entities||[]).map((link:any)=>link.entityId));const chosenRelated=new Set((editing?.related||[]).map((link:any)=>link.rabbitHoleId));const chosenHuman=new Set((editing?.humanLinks||[]).map((link:any)=>link.humanEntryId));
  return <EditorPage title="Browser" subtitle="Questions, trails, and the things they connect to." onBack={onBack} action={<button className="primary" onClick={()=>setEditing(blank)}><Plus/> New rabbit hole</button>}>
    <p className="editorial-hint">Only Published rabbit holes appear publicly. Draft trails can still be linked as “Still exploring.”</p><div className="human-control-list">{items.map((item)=><button key={item.id} onClick={()=>setEditing(item)}><span><strong>{item.title}</strong><small>{item.status} · {item.publicationState}</small></span><ChevronRight/></button>)}</div>
    {editing&&<div className="inline-sheet browser-edit-sheet"><header><strong>{editing.id?"Edit rabbit hole":"New rabbit hole"}</strong><button onClick={()=>setEditing(null)}><X/></button></header><Field label="Title"><input value={editing.title} onChange={(event)=>setEditing({...editing,title:event.target.value,...(!editing.id?{slug:slugify(event.target.value)}:{})})}/></Field><div className="editor-two"><Field label="Slug"><input value={editing.slug} onChange={(event)=>setEditing({...editing,slug:slugify(event.target.value)})}/></Field><Field label="Status"><select value={editing.status} onChange={(event)=>setEditing({...editing,status:event.target.value})}><option value="open">Open</option><option value="paused">Paused</option><option value="closed">Closed</option></select></Field><Field label="Color"><select value={editing.accent} onChange={(event)=>setEditing({...editing,accent:event.target.value})}>{["ember","sun","violet","ocean","moss"].map((value)=><option key={value}>{value}</option>)}</select></Field><Field label="Order"><input type="number" value={editing.sortOrder} onChange={(event)=>setEditing({...editing,sortOrder:Number(event.target.value)})}/></Field></div><Field label="The question"><textarea rows={2} value={editing.centralQuestion} onChange={(event)=>setEditing({...editing,centralQuestion:event.target.value})}/></Field><Field label="Short introduction"><textarea rows={4} value={editing.shortIntro} onChange={(event)=>setEditing({...editing,shortIntro:event.target.value})}/></Field><Field label="Where I’m currently leaning"><textarea rows={6} value={editing.currentTake} onChange={(event)=>setEditing({...editing,currentTake:event.target.value})}/></Field>
      <BrowserBlockEditor blocks={editing.blocks||[]} setBlocks={(blocks)=>setEditing({...editing,blocks})}/><BrowserResourceEditor resources={editing.resources||[]} setResources={(resources)=>setEditing({...editing,resources})}/>
      <section className="browser-link-editor"><h3>Connections</h3><Field label="People, Books, Sources, and Notes"><select value="" onChange={(event)=>{const entity=entityOptions.find((option)=>option.id===event.target.value);if(entity&&!chosenEntities.has(entity.id))setEditing({...editing,entities:[...(editing.entities||[]),{entityId:entity.id,label:"Related",publicRole:entity.kind==="person"?"person":entity.kind==="book"?"book":entity.kind==="note"?"note":"source"}]});}}><option value="">Add an existing Brain object…</option>{entityOptions.filter((option)=>!chosenEntities.has(option.id)).map((option)=><option value={option.id} key={option.id}>{option.title} · {option.kind}</option>)}</select></Field>{(editing.entities||[]).map((link:any)=><RelationRow key={link.entityId} title={entityOptions.find((item)=>item.id===link.entityId)?.title||"Related item"} label={link.label} setLabel={(label)=>setEditing({...editing,entities:editing.entities.map((item:any)=>item.entityId===link.entityId?{...item,label}:item)})} remove={()=>setEditing({...editing,entities:editing.entities.filter((item:any)=>item.entityId!==link.entityId)})}/>)}
      <Field label="Related rabbit holes"><select value="" onChange={(event)=>{const hole=items.find((item)=>item.id===event.target.value);if(hole&&!chosenRelated.has(hole.id)&&hole.id!==editing.id)setEditing({...editing,related:[...(editing.related||[]),{rabbitHoleId:hole.id,label:"Keep going"}]});}}><option value="">Add another trail…</option>{items.filter((item)=>item.id!==editing.id&&!chosenRelated.has(item.id)).map((item)=><option value={item.id} key={item.id}>{item.title} · {item.publicationState}</option>)}</select></Field>{(editing.related||[]).map((link:any)=><RelationRow key={link.rabbitHoleId} title={items.find((item)=>item.id===link.rabbitHoleId)?.title||"Rabbit hole"} label={link.label} setLabel={(label)=>setEditing({...editing,related:editing.related.map((item:any)=>item.rabbitHoleId===link.rabbitHoleId?{...item,label}:item)})} remove={()=>setEditing({...editing,related:editing.related.filter((item:any)=>item.rabbitHoleId!==link.rabbitHoleId)})}/>)}
      <Field label="Human relationships"><select value="" onChange={(event)=>{const human=humanOptions.find((item)=>item.id===event.target.value);if(human&&!chosenHuman.has(human.id))setEditing({...editing,humanLinks:[...(editing.humanLinks||[]),{humanEntryId:human.id,browserLabel:"How this affects how I live",humanLabel:"Explore why I think this"}]});}}><option value="">Connect a Human entry…</option>{humanOptions.filter((item)=>item.section!=="frontiers"&&!chosenHuman.has(item.id)).map((item)=><option value={item.id} key={item.id}>{item.title}</option>)}</select></Field>{(editing.humanLinks||[]).map((link:any)=><RelationRow key={link.humanEntryId} title={humanOptions.find((item)=>item.id===link.humanEntryId)?.title||"Human entry"} label={link.browserLabel} setLabel={(label)=>setEditing({...editing,humanLinks:editing.humanLinks.map((item:any)=>item.humanEntryId===link.humanEntryId?{...item,browserLabel:label}:item)})} remove={()=>setEditing({...editing,humanLinks:editing.humanLinks.filter((item:any)=>item.humanEntryId!==link.humanEntryId)})}/>)}</section>
      <div className="publish-panel"><span><strong>{editing.publicationState==="published"?"Published":"Private draft"}</strong><small>Publishing requires confirmation.</small></span><div><button disabled={saving} onClick={()=>save("draft")}>{editing.publicationState==="published"?"Unpublish":"Save draft"}</button><button className="publish" disabled={saving} onClick={()=>save("published")}>Publish</button></div></div>{editing.id&&<button className="danger-link" onClick={()=>archive(editing.id)}><Archive/> Archive rabbit hole</button>}
    </div>}
  </EditorPage>;
}

function BrowserBlockEditor({blocks,setBlocks}:{blocks:any[];setBlocks:(value:any[])=>void}){return <section className="browser-array-editor"><header><div><strong>Content blocks</strong><small>Let the material determine the shape.</small></div><button onClick={()=>setBlocks([...blocks,{id:crypto.randomUUID(),type:"narrative",heading:"",body:"",items:[]}])}><Plus/> Add block</button></header>{blocks.map((block,index)=><div className="browser-array-row" key={block.id||index}><div className="editor-two"><Field label="Kind"><select value={block.type} onChange={(event)=>setBlocks(blocks.map((item,i)=>i===index?{...item,type:event.target.value}:item))}>{["narrative","experience","question","list","quote"].map((value)=><option key={value}>{value}</option>)}</select></Field><Field label="Heading"><input value={block.heading} onChange={(event)=>setBlocks(blocks.map((item,i)=>i===index?{...item,heading:event.target.value}:item))}/></Field></div><Field label="Body"><textarea rows={5} value={block.body} onChange={(event)=>setBlocks(blocks.map((item,i)=>i===index?{...item,body:event.target.value}:item))}/></Field>{block.type==="list"&&<ListText label="Items" value={block.items||[]} onChange={(items)=>setBlocks(blocks.map((item,i)=>i===index?{...item,items}:item))}/>}<button className="array-remove" onClick={()=>setBlocks(blocks.filter((_,i)=>i!==index))}><X/> Remove</button></div>)}</section>}
function BrowserResourceEditor({resources,setResources}:{resources:any[];setResources:(value:any[])=>void}){return <section className="browser-array-editor"><header><div><strong>External sources</strong><small>Public links only. Private archive material stays out.</small></div><button onClick={()=>setResources([...resources,{id:crypto.randomUUID(),title:"",url:"",resourceType:"article",note:"",publicRole:"start_here",evidenceLayer:"model"}])}><Plus/> Add source</button></header>{resources.map((resource,index)=><div className="browser-array-row" key={resource.id||index}><div className="editor-two"><Field label="Title"><input value={resource.title} onChange={(event)=>setResources(resources.map((item,i)=>i===index?{...item,title:event.target.value}:item))}/></Field><Field label="URL"><input value={resource.url} onChange={(event)=>setResources(resources.map((item,i)=>i===index?{...item,url:event.target.value}:item))}/></Field><Field label="Kind"><select value={resource.resourceType} onChange={(event)=>setResources(resources.map((item,i)=>i===index?{...item,resourceType:event.target.value}:item))}>{["paper","article","book","podcast","video","website"].map((value)=><option key={value}>{value}</option>)}</select></Field><Field label="Placement"><select value={resource.publicRole} onChange={(event)=>setResources(resources.map((item,i)=>i===index?{...item,publicRole:event.target.value}:item))}><option value="start_here">Start Here</option><option value="keep_going">Keep Going</option><option value="context">Context</option></select></Field></div><Field label="Why it’s here"><textarea rows={2} value={resource.note} onChange={(event)=>setResources(resources.map((item,i)=>i===index?{...item,note:event.target.value}:item))}/></Field><button className="array-remove" onClick={()=>setResources(resources.filter((_,i)=>i!==index))}><X/> Remove</button></div>)}</section>}
function RelationRow({title,label,setLabel,remove}:{title:string;label:string;setLabel:(value:string)=>void;remove:()=>void}){return <div className="human-relation-control"><span>{title}</span><input value={label||""} onChange={(event)=>setLabel(event.target.value)}/><button onClick={remove}><X/></button></div>}

function HumanEditor({ items, relationshipOptions, onBack, reload, notify }: { items: any[]; relationshipOptions: any[]; onBack: () => void; reload: () => Promise<void>; notify: (value: string) => void }) {
  const blank = { title:"",slug:"",section:"inner_life",relationshipState:"believe_matters",entryType:"principle",summary:"",currentTake:"",supportingDetails:[],publicationState:"draft",sortOrder:(items.length+1)*10,relationships:[] };
  const [editing,setEditing]=useState<any>(null); const [saving,setSaving]=useState(false);
  async function save(publicationState:"draft"|"published") { if(publicationState==="published"&&!window.confirm("Publish this Human entry to the public OS now?"))return;if(publicationState==="draft"&&editing.publicationState==="published"&&!window.confirm("Unpublish this entry and return it to Draft?"))return;setSaving(true);const response=await action({action:"save-human-entry",item:{...editing,publicationState},confirmPublish:publicationState==="published"});setSaving(false);if(!response.ok)return window.alert(response.error);notify(publicationState==="published"?"Human entry published":"Human draft saved");setEditing(null);await reload();}
  async function archive(id:string){if(!window.confirm("Archive this Human entry? It will disappear publicly but remains recoverable."))return;const response=await action({action:"archive-human-entry",id,confirm:true});if(!response.ok)return window.alert(response.error);notify("Human entry archived");setEditing(null);await reload();}
  const chosenIds=new Set((editing?.relationships||[]).map((link:any)=>link.entityId));
  return <EditorPage title="Human" subtitle="A small, current operating manual—not an archive of everything." onBack={onBack} action={<button className="primary" onClick={()=>setEditing(blank)}><Plus/> New entry</button>}><div className="human-control-list">{items.map((item)=><button key={item.id} onClick={()=>setEditing(item)}><span><strong>{item.title}</strong><small>{humanLabel(item.relationshipState)} · {item.publicationState}</small></span><ChevronRight/></button>)}</div>{editing&&<div className="inline-sheet human-edit-sheet"><header><strong>{editing.id?"Edit Human entry":"New Human entry"}</strong><button onClick={()=>setEditing(null)}><X/></button></header><Field label="Title"><input value={editing.title} onChange={(event)=>setEditing({...editing,title:event.target.value,...(!editing.id?{slug:slugify(event.target.value)}:{})})}/></Field><div className="editor-two"><Field label="Slug"><input value={editing.slug} onChange={(event)=>setEditing({...editing,slug:slugify(event.target.value)})}/></Field><Field label="Section"><select value={editing.section} onChange={(event)=>setEditing({...editing,section:event.target.value})}>{[["inner_life","Inner Life"],["environment","Environment"],["rhythms_recovery","Rhythms & Recovery"],["movement","Movement"],["food","Food"]].map(([value,label])=><option value={value} key={value}>{label}</option>)}</select></Field><Field label="My relationship to this"><select value={editing.relationshipState} onChange={(event)=>setEditing({...editing,relationshipState:event.target.value})}><option value="do_this">I do this</option><option value="do_more">I’d do more of this</option><option value="believe_matters">I believe this matters</option><option value="exploring">I’m exploring this</option></select></Field><Field label="Kind"><select value={editing.entryType} onChange={(event)=>setEditing({...editing,entryType:event.target.value})}><option value="principle">Principle</option><option value="practice">Practice</option><option value="model">Model</option><option value="tool">Tool</option></select></Field></div><Field label="One-sentence summary"><textarea rows={2} value={editing.summary} onChange={(event)=>setEditing({...editing,summary:event.target.value})}/></Field><Field label="My current take"><textarea rows={6} value={editing.currentTake} onChange={(event)=>setEditing({...editing,currentTake:event.target.value})}/></Field><ListText label="Supporting details" value={editing.supportingDetails||[]} onChange={(value)=>setEditing({...editing,supportingDetails:value})}/><Field label="Related Brain object (optional)"><select value="" onChange={(event)=>{const entity=relationshipOptions.find((option)=>option.id===event.target.value);if(entity&&!chosenIds.has(entity.id))setEditing({...editing,relationships:[...(editing.relationships||[]),{entityId:entity.id,label:entity.kind==="person"?"Person":entity.kind==="book"?"Book":"Related"}]});}}><option value="">Add a Person, Book, Source, or Note…</option>{relationshipOptions.filter((option)=>!chosenIds.has(option.id)).map((option)=><option value={option.id} key={option.id}>{option.title} · {option.kind}</option>)}</select></Field>{(editing.relationships||[]).map((link:any)=><div className="human-relation-control" key={link.entityId}><span>{relationshipOptions.find((option)=>option.id===link.entityId)?.title||"Related item"}</span><input value={link.label} onChange={(event)=>setEditing({...editing,relationships:editing.relationships.map((item:any)=>item.entityId===link.entityId?{...item,label:event.target.value}:item)})}/><button onClick={()=>setEditing({...editing,relationships:editing.relationships.filter((item:any)=>item.entityId!==link.entityId)})}><X/></button></div>)}<div className="publish-panel"><span><strong>{editing.publicationState==="published"?"Published":"Private draft"}</strong><small>Publishing requires confirmation.</small></span><div><button disabled={saving} onClick={()=>save("draft")}>{editing.publicationState==="published"?"Unpublish":"Save draft"}</button><button className="publish" disabled={saving} onClick={()=>save("published")}>Publish</button></div></div>{editing.id&&<button className="danger-link" onClick={()=>archive(editing.id)}><Archive/> Archive entry</button>}</div>}</EditorPage>;
}

function EditorPage({ title, subtitle, onBack, action: actionNode, children }: { title: string; subtitle: string; onBack: () => void; action: React.ReactNode; children: React.ReactNode }) { return <section className="control-editor-page"><header><button className="mobile-back" onClick={onBack}><ArrowLeft/> Back</button><div><h1>{title}</h1><p>{subtitle}</p></div>{actionNode}</header><div className="control-form-scroll">{children}</div></section>; }
function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="control-field"><span>{label}</span>{children}</label>; }
function ListText({ label, value, onChange }: { label: string; value: string[]; onChange: (value: string[]) => void }) { return <Field label={`${label} · one per line`}><textarea rows={3} value={value.join("\n")} onChange={(event)=>onChange(event.target.value.split("\n").map((item)=>item.trim()).filter(Boolean))}/></Field>; }
function Status({ state }: { state: string }) { return <span className={`editor-status is-${state}`}><i/>{state === "published" ? "Published" : "Draft"}</span>; }
function humanLabel(state:string){return state==="do_this"?"I do this":state==="do_more"?"I’d do more of this":state==="exploring"?"I’m exploring this":"I believe this matters";}
function ItemList({ title, items, setItems }: { title: string; items: string[]; setItems: (items: string[]) => void }) { return <section className="item-list"><header><strong>{title}</strong><button onClick={()=>setItems([...items,""])}><ListPlus/> Add</button></header>{items.map((item,index)=><div key={index}><input value={item} onChange={(event)=>setItems(items.map((value,i)=>i===index?event.target.value:value))} placeholder="Short and human"/><button disabled={index===0} onClick={()=>setItems(moveItem(items,index,index-1))}><ArrowUp/></button><button disabled={index===items.length-1} onClick={()=>setItems(moveItem(items,index,index+1))}><ArrowDown/></button><button onClick={()=>setItems(items.filter((_,i)=>i!==index))}><X/></button></div>)}</section>; }
async function action(body: any) { const response=await fetch("/api/control/action",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const value=await response.json();return{ok:response.ok,...value}; }
function slugify(value:string){return value.toLowerCase().trim().replace(/['’]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");}
function newBlock(type:BlockType,text=""):Block{return{id:crypto.randomUUID(),type,text};}
function moveItem<T>(items:T[],from:number,to:number){if(to<0||to>=items.length)return items;const next=[...items];const [item]=next.splice(from,1);next.splice(to,0,item);return next;}
function parseMarkdown(markdown:string):Block[]{if(!markdown.trim())return[newBlock("paragraph")];return markdown.split("\n").filter((line)=>line.trim()).map((line)=>line.startsWith("## ")?newBlock("heading2",line.slice(3)):line.startsWith("# ")?newBlock("heading1",line.slice(2)):line.startsWith("- ")?newBlock("bullet",line.slice(2)):line.startsWith("> ")?newBlock("quote",line.slice(2)):newBlock("paragraph",line));}
function serializeBlocks(blocks:Block[]){let output="";let previous:BlockType|null=null;for(const block of blocks){if(!block.text.trim())continue;const prefix=block.type==="heading1"?"# ":block.type==="heading2"?"## ":block.type==="bullet"?"- ":block.type==="quote"?"> ":"";const separator=output&&!(previous==="bullet"&&block.type==="bullet")?"\n\n":output?"\n":"";output+=separator+prefix+block.text.trim();previous=block.type;}return output;}
